await foreach (var o in ReadOrdersAsync()) Handle(o);

// примерно так это разворачивает компилятор:
var e = ReadOrdersAsync().GetAsyncEnumerator();   // 1) тело ещё не запускалось
try
{
    while (await e.MoveNextAsync())   // 2–5) ValueTask<bool>: работа до следующего yield
        Handle(e.Current);            // 3) элемент; генератор стоит на yield
}
finally { await e.DisposeAsync(); }   // 6) finally генератора — даже после break

