    [EnumeratorCancellation] CancellationToken ct = default)
{
    await foreach (var line in File.ReadLinesAsync(path, ct))   // токен — дальше
        yield return Parse(line);
}

await foreach (var o in ReadOrdersAsync().WithCancellation(cts.Token))
    Handle(o);   // токен ушёл в GetAsyncEnumerator → в параметр ct

